




"use strict";

const { parseResource } = require("../util/identifier");
















const quoteMeta = (str) => str.replace(/[-[\]\\/{}()*+?.^$|]/g, "\\$&");






const splitContextFromPrefix = (prefix) => {
	const idx = prefix.lastIndexOf("/");
	let context = ".";
	if (idx >= 0) {
		context = prefix.slice(0, idx);
		prefix = `.${prefix.slice(idx)}`;
	}
	return {
		context,
		prefix
	};
};























module.exports.create = (
	Dep,
	range,
	param,
	expr,
	options,
	contextOptions,
	parser,
	...depArgs
) => {
	if (param.isTemplateString()) {
		const quasis =  (param.quasis);
		const prefixRaw =  (quasis[0].string);
		const postfixRaw =
			
			(quasis.length > 1 ? quasis[quasis.length - 1].string : "");

		const valueRange =  (param.range);
		const { context, prefix } = splitContextFromPrefix(prefixRaw);
		const {
			path: postfix,
			query,
			fragment
		} = parseResource(postfixRaw, parser);

		
		
		const innerQuasis = quasis.slice(1, -1);
		const innerRegExp =
			 (options.wrappedContextRegExp).source +
			innerQuasis
				.map(
					(q) =>
						quoteMeta( (q.string)) +
						 (options.wrappedContextRegExp).source
				)
				.join("");

		
		
		
		
		
		
		
		
		
		const regExp = new RegExp(
			`^${quoteMeta(prefix)}${innerRegExp}${quoteMeta(postfix)}$`
		);
		const dep = new Dep(
			{
				request: context + query + fragment,
				recursive:  (options.wrappedContextRecursive),
				regExp,
				mode: "sync",
				...contextOptions
			},
			range,
			valueRange,
			...depArgs
		);
		dep.loc = parser.getLocation(expr);

		
		const replaces = [];
		const parts =  (param.parts);

		for (const [i, part] of parts.entries()) {
			if (i % 2 === 0) {
				
				let range =  (part.range);
				let value =  (part.string);
				if (param.templateStringKind === "cooked") {
					value = JSON.stringify(value);
					value = value.slice(1, -1);
				}
				if (i === 0) {
					
					value = prefix;
					range = [
						 (param.range)[0],
						 (part.range)[1]
					];
					value =
						(param.templateStringKind === "cooked" ? "`" : "String.raw`") +
						value;
				} else if (i === parts.length - 1) {
					
					value = postfix;
					range = [
						 (part.range)[0],
						 (param.range)[1]
					];
					value = `${value}\``;
				} else if (
					part.expression &&
					part.expression.type === "TemplateElement" &&
					part.expression.value.raw === value
				) {
					
					continue;
				}
				replaces.push({
					range,
					value
				});
			} else {
				
				parser.walkExpression(
					
					(part.expression)
				);
			}
		}

		dep.replaces = replaces;
		dep.critical =
			options.wrappedContextCritical &&
			"a part of the request of a dependency is an expression";
		return dep;
	} else if (
		param.isWrapped() &&
		((param.prefix && param.prefix.isString()) ||
			(param.postfix && param.postfix.isString()))
	) {
		const prefixRaw =
			
			(param.prefix && param.prefix.isString() ? param.prefix.string : "");
		const postfixRaw =
			
			(param.postfix && param.postfix.isString() ? param.postfix.string : "");
		const prefixRange =
			param.prefix && param.prefix.isString() ? param.prefix.range : null;
		const postfixRange =
			param.postfix && param.postfix.isString() ? param.postfix.range : null;
		const valueRange =  (param.range);
		const { context, prefix } = splitContextFromPrefix(prefixRaw);
		const {
			path: postfix,
			query,
			fragment
		} = parseResource(postfixRaw, parser);
		const regExp = new RegExp(
			`^${quoteMeta(prefix)}${
				 (options.wrappedContextRegExp).source
			}${quoteMeta(postfix)}$`
		);
		const dep = new Dep(
			{
				request: context + query + fragment,
				recursive:  (options.wrappedContextRecursive),
				regExp,
				mode: "sync",
				...contextOptions
			},
			range,
			valueRange,
			...depArgs
		);
		dep.loc = parser.getLocation(expr);
		
		const replaces = [];
		if (prefixRange) {
			replaces.push({
				range: prefixRange,
				value: JSON.stringify(prefix)
			});
		}
		if (postfixRange) {
			replaces.push({
				range: postfixRange,
				value: JSON.stringify(postfix)
			});
		}
		dep.replaces = replaces;
		dep.critical =
			options.wrappedContextCritical &&
			"a part of the request of a dependency is an expression";

		if (parser && param.wrappedInnerExpressions) {
			for (const part of param.wrappedInnerExpressions) {
				if (part.expression) {
					parser.walkExpression(
						
						(part.expression)
					);
				}
			}
		}

		return dep;
	}
	const dep = new Dep(
		{
			request:  (options.exprContextRequest),
			recursive:  (options.exprContextRecursive),
			regExp:  (options.exprContextRegExp),
			mode: "sync",
			...contextOptions
		},
		range,
		 (param.range),
		...depArgs
	);
	dep.loc = parser.getLocation(expr);
	dep.critical =
		options.exprContextCritical &&
		"the request of a dependency is an expression";

	parser.walkExpression( (param.expression));

	return dep;
};
